def intr(u,no,data):ctx['fault']=(no,u.reg_read(UC_X86_REG_IP));u.emu_stop()
u.hook_add(UC_HOOK_INTR,intr)
def signed(v,bits):v&=(1<<bits)-1;return v-(1<<bits) if v>>(bits-1) else v
